// Turn the fields set in "Set The Default Policy" into one row per setting, so the whole
// configuration lives in a table and changes without editing the workflow. The notes stay here
// because they are documentation for whoever opens the table, not values to configure.
const f = $input.first().json;
const NOTES = {
  mode: 'mask | pseudonymise | remove. Applies to every detector.',
  pseudonym_key: 'REQUIRED for pseudonymise mode. Any long random string. Pseudonymise REFUSES to run while this is empty, because an unkeyed hash of an email address can be reversed with a word list. Changing it changes every token.',
  detect_email: 'Email addresses.',
  detect_iban: 'IBANs, checked with mod-97 before redacting.',
  detect_card: 'Payment cards, checked with Luhn before redacting.',
  detect_phone: 'Phone numbers with at least 8 digits.',
  detect_ip: 'IPv4 addresses.',
  report_unclassified: 'Report strings that could be personal data but matched no detector. Turning this off does not make them safe, it only hides them.'
};
return Object.keys(NOTES).map(k => ({
  json: { setting: k, value: String(f[k] === undefined ? '' : f[k]), note: NOTES[k] }
}));

// Known-dirty inputs with known answers, fed through THE SAME detector the callers use.
// The policy arrives on this node's input and is attached to every probe, so the detector reads it
// from the item and never has to reach across to a node on the other entry path.
const policy = $input.all().map(i => i.json).filter(r => r && r.setting);
// The invalid pairs are the point: a pattern that looks right but fails its check must be left
// alone, or every order number becomes a redacted card.
const probes = [
  { json: { __selftest: true, requested_by: 'self test', expect: { email: 1 },
            payload: { note: 'write to user@example.com about it' } } },
  { json: { __selftest: true, requested_by: 'self test', expect: { iban: 1 },
            payload: { note: 'paid from DE893704+1234567890 yesterday' } } },
  { json: { __selftest: true, requested_by: 'self test', expect: {},
            payload: { note: 'reference DE893704+1234567890 is not a real iban' } } },
  { json: { __selftest: true, requested_by: 'self test', expect: { card: 1 },
            payload: { note: 'card 4111 1111 1111 1111 on file' } } },
  { json: { __selftest: true, requested_by: 'self test', expect: {},
            payload: { note: 'order 4111111111111112 shipped' } } },
  { json: { __selftest: true, requested_by: 'self test', expect: { ip: 1 },
            payload: { note: 'seen from 192.168.15.22 twice' } } },
  { json: { __selftest: true, requested_by: 'self test', expect: { phone: 1 },
            payload: { note: 'ring +1234567890 in the morning' } } },
  { json: { __selftest: true, requested_by: 'self test', expect: {},
            payload: { note: 'Maria Gonzalez asked for a copy' } } }
];
return probes.map(p => ({ json: Object.assign({}, p.json, { __policy: policy }) }));

// Hand the caller's items on with the policy attached, so the detector reads everything it needs
// from the item it is given. Without this the policy read would sit between the caller and the
// detector, and the detector's input would BE the policy rows rather than the items to redact.
const policy = $input.all().map(i => i.json).filter(r => r && r.setting);
const items = $('When Another Workflow Calls This').all().map(i => i.json);
return items.map(it => ({ json: Object.assign({}, it, { __policy: policy }) }));

// Deterministic redaction. No model: a value either matches a validated pattern or it does not,
// and a model would add a confident opinion about text it cannot verify.
const crypto = require('crypto');

// Items arrive carrying the policy, attached by whichever node fed this one. Reading the policy
// from a named node instead would tie the two entry paths together: the caller path and the self
// test path would each have to reference a node that only exists on the other one.
const inputItems = $input.all().map(i => i.json);
const policyRows = ((inputItems[0] || {}).__policy || []).filter(r => r && r.setting);
const P = {};
for (const r of policyRows) P[String(r.setting)] = String(r.value === undefined ? '' : r.value);

const mode = (P.mode || 'mask').toLowerCase();
const key = P.pseudonym_key || '';
const on = k => String(P['detect_' + k] || 'yes').toLowerCase() === 'yes';
const reportUnclassified = String(P.report_unclassified || 'yes').toLowerCase() === 'yes';

// ---- FAIL CLOSED. Pseudonymise without a key would be a plain hash, and a plain hash of an
// email address is reversible with a word list. Refuse rather than quietly weaken the mode.
const policyMissing = !policyRows.length;
const keyMissing = mode === 'pseudonymise' && !key;

// ---- validators, so a pattern alone never decides
function luhnOk(digits) {
  let sum = 0, alt = false;
  for (let i = digits.length - 1; i >= 0; i--) {
    let n = Number(digits[i]);
    if (alt) { n *= 2; if (n > 9) n -= 9; }
    sum += n; alt = !alt;
  }
  return digits.length >= 13 && digits.length <= 19 && sum % 10 === 0;
}
function ibanOk(raw) {
  const s = raw.replace(/[^0-9A-Za-z]/g, '').toUpperCase();
  if (s.length < 15 || s.length > 34) return false;
  if (!/^[A-Z]{2}[0-9]{2}[0-9A-Z]+$/.test(s)) return false;
  const moved = s.slice(4) + s.slice(0, 4);
  let rem = 0;
  for (const ch of moved) {
    const v = /[0-9]/.test(ch) ? ch : String(ch.charCodeAt(0) - 55);
    for (const d of v) rem = (rem * 10 + Number(d)) % 97;
  }
  return rem === 1;
}

// ---- replacements
function token(value, label) {
  if (mode === 'remove') return '[' + label + ' removed]';
  if (mode === 'pseudonymise') {
    const h = crypto.createHmac('sha256', key).update(String(value)).digest('hex').slice(0, 16);
    return '[' + label + ':' + h + ']';
  }
  // mask keeps enough shape to be recognisable without being readable
  const s = String(value);
  if (label === 'email') {
    const at = s.indexOf('@');
    if (at > 0) return s[0] + '***@' + s.slice(at + 1);
  }
  const keep = s.replace(/[^0-9A-Za-z]/g, '').slice(-4);
  return '[' + label + ' ****' + keep + ']';
}

// ---- detectors. Order matters: the validated ones run first so their digits are consumed before
// the phone detector, which is the loosest, ever sees them.
const DETECTORS = [
  { name: 'email', on: on('email'), re: /[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g, valid: () => true },
  { name: 'iban',  on: on('iban'),  re: /\b[A-Z]{2}[0-9]{2}(?:[ ]?[0-9A-Z]{2,4}){2,7}\b/g, valid: ibanOk },
  { name: 'card',  on: on('card'),  re: /\b(?:[0-9][ -]?){13,19}\b/g,
    valid: v => luhnOk(v.replace(/[^0-9]/g, '')) },
  { name: 'phone', on: on('phone'), re: /(?:\+|00)[0-9][0-9 ()\-.]{7,}[0-9]|\b0[0-9][0-9 ()\-.]{7,}[0-9]\b/g,
    // E.164 caps a phone number at 15 digits. Without the upper bound the phone detector ate the
    // tail of a REJECTED iban, DE893704+1234567890, and reported it as a redacted phone: the
    // look-alike probe caught it. A long digit run that is not a valid anything belongs in
    // unclassified_candidates, not in a confident redaction.
    edgeSafe: true,
    valid: v => { const n = v.replace(/[^0-9]/g, '').length; return n >= 8 && n <= 15; } },
  { name: 'ip',    on: on('ip'),    re: /\b(?:(?:25[0-5]|2[0-4][0-9]|1?[0-9]{1,2})\.){3}(?:25[0-5]|2[0-4][0-9]|1?[0-9]{1,2})\b/g,
    valid: () => true }
];

// anything that still looks like it could identify somebody, after every detector has had its turn
const UNCLASSIFIED = [
  { name: 'long digit run', re: /\b[0-9]{6,}\b/g },
  { name: 'possible name', re: /\b[A-Z][a-z]{2,}\s+[A-Z][a-z]{2,}\b/g }
];

const counts = {};
let redactedTotal = 0;
const unclassified = [];

function scrub(text) {
  let out = String(text);
  for (const d of DETECTORS) {
    if (!d.on) continue;
    out = out.replace(d.re, function (m) {
      const offset = arguments[arguments.length - 2];
      const whole = arguments[arguments.length - 1];
      if (d.edgeSafe && offset > 0 && /[0-9A-Za-z]/.test(whole[offset - 1])) return m;
      if (!d.valid(m)) return m;
      counts[d.name] = (counts[d.name] || 0) + 1;
      redactedTotal++;
      return token(m, d.name);
    });
  }
  if (reportUnclassified) {
    for (const u of UNCLASSIFIED) {
      const found = out.match(u.re);
      if (found) for (const f of found) unclassified.push(u.name + ': ' + String(f).slice(0, 24));
    }
  }
  return out;
}

function walk(v) {
  if (typeof v === 'string') return scrub(v);
  if (Array.isArray(v)) return v.map(walk);
  if (v && typeof v === 'object') { const o = {}; for (const k of Object.keys(v)) o[k] = walk(v[k]); return o; }
  return v;
}

// Keys this workflow puts on the item itself. They are plumbing, not the caller's
// data, and they must never be handed back. __policy in particular carries the whole
// policy table, pseudonym_key included, so returning it would hand the caller the one
// secret this workflow has. Found by calling with an item that had no payload key.
const INTERNAL = ['__policy', '__selftest', 'requested_by', 'expect'];
function withoutInternal(o) {
  if (!o || typeof o !== 'object' || Array.isArray(o)) return o;
  const c = {};
  for (const k of Object.keys(o)) if (INTERNAL.indexOf(k) === -1) c[k] = o[k];
  return c;
}

const items = inputItems;
const out = [];
for (const item of items) {
  const isSelfTest = item && item.__selftest === true;
  // No payload key means the caller sent the record itself. Take it, minus the plumbing.
  const payload = item && item.payload !== undefined ? item.payload : withoutInternal(item);
  const askedBy = String((item && item.requested_by) || 'unknown').slice(0, 80);

  if (policyMissing || keyMissing) {
    out.push({ json: {
      __selftest: isSelfTest,
      ok: false,
      reason: policyMissing
        ? 'the redaction_policy table is empty, so nothing was redacted. An empty policy does not mean there is nothing to redact; run Set Up Tables first'
        : 'mode is pseudonymise but pseudonym_key is empty, so nothing was redacted. An unkeyed hash of an email address can be reversed with a word list; set a key or use mask',
      mode, requested_by: askedBy, redacted: payload,
      values_redacted: 0, by_detector: {}, unclassified_candidates: [],
      blind_spots: 'Refused before looking.'
    } });
    continue;
  }

  for (const k of Object.keys(counts)) delete counts[k];
  redactedTotal = 0;
  unclassified.length = 0;

  const cleaned = walk(payload);
  // The SIZE of the payload once serialised, in characters. Named for what it is: an earlier
  // version called this fieldCount and wrote it to a column called fields_seen, so an item with
  // three fields was logged as 180 and read as 180 fields.
  const payloadChars = JSON.stringify(payload).length;

  out.push({ json: {
    __selftest: isSelfTest,
    ok: true,
    mode, requested_by: askedBy,
    redacted: cleaned,
    values_redacted: redactedTotal,
    by_detector: JSON.parse(JSON.stringify(counts)),
    unclassified_candidates: unclassified.slice(0, 25),
    payload_chars: payloadChars,
    // Always present, null when there is nothing to say. A key that exists only on the refusal
    // branch makes every reader of this output guess which shape they have.
    reason: null,
    blind_spots: 'Personal names are not detected: no pattern distinguishes a person from a place or a product. Anything listed under unclassified_candidates was left in place. A result with nothing redacted is not evidence that the item holds no personal data.'
  } });
}
return out.map(o => ({ json: o.json }));

// What the calling workflow receives. The refusal is an answer, not an error, and the report is
// returned whether anything was found or not, so a caller cannot read silence as "clean".
const d = $('Redact The Item').all().map(i => i.json);
return d.map(x => ({ json: {
  ok: x.ok,
  redacted: x.redacted,
  values_redacted: x.values_redacted,
  by_detector: x.by_detector,
  unclassified_candidates: x.unclassified_candidates,
  mode: x.mode,
  reason: x.reason || null,
  blind_spots: x.blind_spots
} }));

// Compare what the detector did against what each probe said it should do. A self test that
// cannot fail is decoration, so this reports the first mismatch rather than a count.
const rows = $input.all().map(i => i.json);
const probes = $('Build The Probe Items').all().map(i => i.json);

const problems = [];
for (let i = 0; i < rows.length; i++) {
  const got = rows[i].by_detector || {};
  const want = (probes[i] && probes[i].expect) || {};
  const keys = Object.keys(want).concat(Object.keys(got));
  for (const k of keys) {
    const a = Number(want[k] || 0), c = Number(got[k] || 0);
    if (a !== c) problems.push('probe ' + (i + 1) + ': expected ' + a + ' ' + k + ', got ' + c);
  }
}

// the two negative probes are the ones that catch a detector that fires on anything
const negatives = rows.filter((r, i) => Object.keys((probes[i] || {}).expect || {}).length === 0);
const negativeLeaks = negatives.filter(r => r.values_redacted > 0).length;

const nameProbe = rows[rows.length - 1];
const namesLeftAlone = nameProbe && nameProbe.values_redacted === 0;

const summary = problems.length
  ? 'SELF TEST FAILED. ' + problems.length + ' mismatch(es): ' + problems.slice(0, 6).join('; ')
  : 'Self test passed. ' + rows.length + ' probes, every detector fired exactly where it should and '
    + negatives.length + ' look-alike value(s) were correctly left alone. '
    + (namesLeftAlone ? 'The name probe was left in place, which is the known blind spot, not a bug.' : '');

return [{ json: {
  checked_at: new Date().toISOString(),
  probes: rows.length,
  mismatches: problems.length,
  negative_leaks: negativeLeaks,
  passed: problems.length === 0,
  summary
} }];
